// generic-stack | stack-operations / array-backed | negative / p1

class Stack<T> {
  private readonly items: T[] = [];

  push(value: T): void {
    this.items.push(value);
  }

  pop(): T {
    const value = this.items.pop();
    if (value === undefined) throw new Error("stack is empty");
    return value;
  }

  peek(): T | undefined {
    return this.items[this.items.length - 1];
  }

  get size(): number {
    return this.items.length;
  }
}

const stack = new Stack<number>();
stack.push(-3);
stack.push(-5);
stack.push(0);
stack.push(3);
stack.push(7);
console.log(stack.size, stack.peek(), stack.pop());

// config-parser | parse-and-validate / split-scan | duplicates / p2

function parseConfig(input: string): Record<string, string> {
  const result: Record<string, string> = {};
  for (const rawLine of input.split("\n")) {
    const line = rawLine.trim();
    if (line.length === 0 || line.startsWith("#")) continue;
    const separator = line.indexOf("=");
    if (separator <= 0) throw new Error(`invalid line: ${line}`);
    const key = line.slice(0, separator).trim();
    const value = line.slice(separator + 1).trim();
    if (key in result) throw new Error(`duplicate key: ${key}`);
    result[key] = value;
  }
  return result;
}

