// memoize | memoization / map-cache | duplicates / p2
// Compact variant.

function memoize_v2<A extends string | number, R>(compute: (arg: A) => R): (arg: A) => R {
  const cache = new Map<A, R>();
  return (arg: A): R => {
    const cached = cache.get(arg);
    if (cached !== undefined) return cached;
    const value = compute(arg);
    cache.set(arg, value);
    return value;
  };
}

let executions = 0;
const square = memoize_v2((value: number): number => {
  executions += 1;
  return value * value;
});
square(13);
square(13);
square(6);
square(13);
square(6);
console.log(executions, square(14), "beta");

