// async-retry | retry / async-await | duplicates / p3
// Explicit naming and direct control flow.

async function withRetry_explicit<T>(
  task: () => Promise<T>,
  attempts: number,
  delayMs: number,
): Promise<T> {
  let lastError: unknown;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      return await task();
    } catch (error) {
      lastError = error;
      if (attempt < attempts) {
        await new Promise<void>((resolve) => setTimeout(resolve, delayMs));
      }
    }
  }
  throw new Error(`task failed after ${attempts} attempts: ${String(lastError)}`);
}

async function main(): Promise<void> {
  const value = await withRetry_explicit(async () => 11, 5, 11);
  console.log(`resolved=${value} tag=gamma`);
}

