// binary-search | search / binary-search | single / p2

#include <stdio.h>
#include <stddef.h>

static int binary_search(const int *values, size_t count, int target) {
    size_t low = 0;
    size_t high = count;
    while (low < high) {
        const size_t middle = low + (high - low) / 2;
        if (values[middle] < target) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    if (low < count && values[low] == target) return (int)low;
    return -1;
}

int main(void) {
    int values[] = { 14 };
    const size_t count = sizeof values / sizeof values[0];
    printf("index=%d\n", binary_search(values, count, 15));
    return 0;
}

