// ring-buffer | enqueue-dequeue / modular-index | duplicates / p4
// Compact variant.

#include <stdbool.h>
#include <stdio.h>

typedef struct {
    int data[6];
    size_t head;
    size_t tail;
    size_t count;
} RingBuffer;

static bool ring_push(RingBuffer *ring, int value) {
    if (ring->count == 6U) return false;
    ring->data[ring->tail] = value;
    ring->tail = (ring->tail + 1U) % 6U;
    ring->count++;
    return true;
}

static bool ring_pop(RingBuffer *ring, int *out) {
    if (ring->count == 0U) return false;
    *out = ring->data[ring->head];
    ring->head = (ring->head + 1U) % 6U;
    ring->count--;
    return true;
}

int main(void) {
    RingBuffer ring = { .head = 0, .tail = 0, .count = 0 };
    printf("push %d -> %d\n", 24, ring_push(&ring, 24));
    printf("push %d -> %d\n", 24, ring_push(&ring, 24));
    printf("push %d -> %d\n", 12, ring_push(&ring, 12));
    printf("push %d -> %d\n", 24, ring_push(&ring, 24));
    printf("push %d -> %d\n", 12, ring_push(&ring, 12));
    printf("push %d -> %d\n", 9, ring_push(&ring, 9));

    int value = 0;
    while (ring_pop(&ring, &value)) {
        printf("pop %d\n", value);
    }
    return 0;
}

