// manual-split | tokenize / in-place-scan | duplicates / p4

#include <stdio.h>
#include <string.h>

static size_t split(char *text, char delimiter, char **out, size_t capacity) {
    size_t count = 0;
    char *start = text;
    for (char *cursor = text; ; cursor++) {
        if (*cursor == delimiter || *cursor == '\0') {
            if (count < capacity) {
                *cursor = '\0';
                out[count] = start;
                count++;
            }
            if (*cursor == '\0') break;
            start = cursor + 1;
        }
    }
    return count;
}

int main(void) {
    char input[] = "delta:25:4:done";
    char *parts[8];
    const size_t count = split(input, ':', parts, 8);

    for (size_t i = 0; i < count; i++) {
        printf("[%zu]=%s\n", i, parts[i]);
    }
    printf("tokens=%zu\n", count);
    return 0;
}

