// binary-search | search / binary-search | large / p3
// Explicit naming and direct control flow.

import java.util.Arrays;

public final class Demo {
    static int binarySearch_explicit(int[] values, int target) {
        int low = 0;
        int high = values.length - 1;
        while (low <= high) {
            int middle = low + (high - low) / 2;
            if (values[middle] == target) return middle;
            if (values[middle] < target) low = middle + 1;
            else high = middle - 1;
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] values = {1000, 1014, 1028, 1042, 1056, 1070, 1084, 1098, 1112, 1126, 1140, 1154};
        Arrays.sort(values);
        int index = binarySearch_explicit(values, 1084);
        System.out.println("index=" + index);
    }
}

