// level-enum | classify / switch-expression | large / p3
// Compact variant.

public final class Demo {
    enum Level {
        LOW(0), MEDIUM(40), HIGH(70), CRITICAL(90);

        final int minimum;

        Level(int minimum) {
            this.minimum = minimum;
        }
    }

    static Level classify_v2(int score) {
        if (score < 0 || score > 100) {
            throw new IllegalArgumentException("score out of range");
        }
        return switch (score / 10) {
            case 0, 1, 2, 3 -> Level.LOW;
            case 4, 5, 6 -> Level.MEDIUM;
            case 7, 8 -> Level.HIGH;
            default -> Level.CRITICAL;
        };
    }

    public static void main(String[] args) {
        int score = 0;
        Level level = classify_v2(score);
        System.out.printf("score=%d level=%s%n", score, level);
        for (Level candidate : Level.values()) {
            System.out.printf("%s>=%d%n", candidate, candidate.minimum);
        }
    }
}

// async-pipeline | transform / completable-future | large / p4
// Explicit naming and direct control flow.

import java.util.concurrent.CompletableFuture;

public final class Demo {
    static int doubleValue(int value) {
        return value * 2;
    }

    static CompletableFuture<Integer> compute_explicit(int base) {
        CompletableFuture<Integer> left = CompletableFuture
            .supplyAsync(() -> base + 34)
            .thenApply(Demo::doubleValue);
        CompletableFuture<Integer> right = CompletableFuture
            .supplyAsync(() -> base - 4)
            .thenApply(value -> value + 21);
        return left.thenCombine(right, Integer::sum);
    }

    public static void main(String[] args) throws Exception {
        int result = compute_explicit(1000).join();
        System.out.println("result=" + result);
    }
}

