// generic-max | select-maximum / generic-constraint | duplicates / p4
// Compact variant.

using System;
using System.Collections.Generic;
using System.Linq;

namespace Samples;

public static class Demo
{
    public static T Max_v2<T>(IReadOnlyList<T> values) where T : IComparable<T>
    {
        if (values.Count == 0) throw new ArgumentException("empty list");
        var best = values[0];
        for (var i = 1; i < values.Count; i++)
        {
            if (values[i].CompareTo(best) > 0) best = values[i];
        }
        return best;
    }

    public static void Main()
    {
        Console.WriteLine("int=" + Max_v2(new[] { 24, 24, 12, 24, 12, 9 }));
        Console.WriteLine("str=" + Max_v2(new[] { "delta", "code", "review" }));
        Console.WriteLine("double=" + Max_v2(new[] { 24.5, 24.25 }));
        Console.WriteLine("count=" + new[] { 1, 2, 3 }.Count());
    }
}

// word-frequency | count-occurrences / dictionary | duplicates / p3
// Explicit naming and direct control flow.

using System;
using System.Collections.Generic;
using System.Linq;

namespace Samples;

public static class Demo
{
    public static Dictionary<string, int> CountWords_explicit(string text)
    {
        var counts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        var cleaned = new string(text.Select(ch => char.IsLetterOrDigit(ch) ? ch : ' ').ToArray());
        foreach (var word in cleaned.Split(' ', StringSplitOptions.RemoveEmptyEntries))
        {
            counts.TryGetValue(word, out var current);
            counts[word] = current + 1;
        }
        return counts;
    }

    public static void Main()
    {
        const string text = "gamma gamma code review gamma gamma";
        var top = CountWords_explicit(text)
            .OrderByDescending(pair => pair.Value)
            .ThenBy(pair => pair.Key)
            .Take(5);

        foreach (var pair in top)
        {
            Console.WriteLine(pair.Key + ":" + pair.Value);
        }
    }
}

