// binary-search | search / binary-search | large / p3
// Documented reference implementation.

using System;

namespace Samples;

public static class Demo
{
    public static int BinarySearch_doc(int[] values, int target)
    {
        if (values is null) throw new ArgumentNullException(nameof(values));
        var low = 0;
        var high = values.Length - 1;
        while (low <= high)
        {
            var middle = low + (high - low) / 2;
            if (values[middle] == target) return middle;
            if (values[middle] < target) low = middle + 1;
            else high = middle - 1;
        }
        return -1;
    }

    public static void Main()
    {
        var values = new[] { 1000, 1014, 1028, 1042, 1056, 1070, 1084, 1098, 1112, 1126, 1140, 1154 };
        Array.Sort(values);
        Console.WriteLine("index=" + BinarySearch_doc(values, 1084));
        Console.WriteLine(string.Join(",", values));
    }
}

