using System.Linq;

namespace Samples;

public static class Demo
{
    public sealed record Summary(long Total, int Count, double Average);

    public static Summary Summarize(int[] values)
    {
        if (values is null) throw new ArgumentNullException(nameof(values));
        var total = values.Sum(value => (long)value);
        var count = values.Length;
        var average = count == 0 ? 0.0 : (double)total / count;
        return new Summary(total, count, average);
    }

    public static void Main()
    {
        var sample = new[] { 1000, 1014, 1028, 1042, 1056, 1070, 1084, 1098, 1112, 1126, 1140, 1154 };
        var summary = Summarize(sample);
        Console.WriteLine("total=" + summary.Total + " average=" + summary.Average.ToString("F2"));
    }
}

// binary-search | search / binary-search | large / p4

using System;

namespace Samples;

public static class Demo
{
    public static int BinarySearch(int[] values, int target)
    {
        if (values is null) throw new ArgumentNullException(nameof(values));
        var low = 0;
        var high = values.Length - 1;
        while (low <= high)
        {
            var middle = low + (high - low) / 2;
            if (values[middle] == target) return middle;
            if (values[middle] < target) low = middle + 1;
            else high = middle - 1;
        }
        return -1;
    }

    public static void Main()
    {
        var values = new[] { 1000, 1009, 1018, 1027, 1036, 1045, 1054, 1063, 1072, 1081, 1090, 1099 };
        Array.Sort(values);
        Console.WriteLine("index=" + BinarySearch(values, 1054));
        Console.WriteLine(string.Join(",", values));
    }
}

