}

// generic-max | select-maximum / generic-constraint | large / p2
// Explicit naming and direct control flow.

using System;
using System.Collections.Generic;
using System.Linq;

namespace Samples;

public static class Demo
{
    public static T Max_explicit<T>(IReadOnlyList<T> values) where T : IComparable<T>
    {
        if (values.Count == 0) throw new ArgumentException("empty list");
        var best = values[0];
        for (var i = 1; i < values.Count; i++)
        {
            if (values[i].CompareTo(best) > 0) best = values[i];
        }
        return best;
    }

    public static void Main()
    {
        Console.WriteLine("int=" + Max_explicit(new[] { 1000, 1003, 1006, 1009, 1012, 1015, 1018, 1021, 1024, 1027, 1030, 1033 }));
        Console.WriteLine("str=" + Max_explicit(new[] { "beta", "code", "review" }));
        Console.WriteLine("double=" + Max_explicit(new[] { 1000.5, 1003.25 }));
        Console.WriteLine("count=" + new[] { 1, 2, 3 }.Count());
    }
}

