        Console.WriteLine("str=" + Max_doc(new[] { "gamma", "code", "review" }));
        Console.WriteLine("double=" + Max_doc(new[] { 10.5, 10.25 }));
        Console.WriteLine("count=" + new[] { 1, 2, 3 }.Count());
    }
}

