// generic-max | select-maximum / trait-bound | large / p3
// Explicit naming and direct control flow.

fn max_value_explicit<T: PartialOrd + Copy>(values: &[T]) -> Option<T> {
    let mut best = *values.first()?;
    for value in values.iter().skip(1) {
        if *value > best {
            best = *value;
        }
    }
    Some(best)
}

fn main() {
    let numbers: Vec<i64> = vec![1000, 1014, 1028, 1042, 1056, 1070, 1084, 1098, 1112, 1126, 1140, 1154];
