// binary-search | search / binary-search | duplicates / p1
// Defensive variant with descriptive identifiers.

fn binary_search_safe(values: &[i64], target: i64) -> Option<usize> {
    let mut low = 0usize;
    let mut high = values.len();

    while low < high {
        let middle = low + (high - low) / 2;
        if values[middle] == target {
            return Some(middle);
        }
        if values[middle] < target {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    None
}

fn main() {
    let mut values: Vec<i64> = vec![6, 6, 6, 9, 9, 10];
    values.sort();
    match binary_search_safe(&values, 9) {
        Some(index) => println!("found at {index}"),
        None => println!("not found"),
    }
    println!("{values:?}");
}

