    let shapes: Vec<Box<dyn Shape>> = vec![
        Box::new(Circle { radius: 7.0 }),
        Box::new(Rectangle { width: 7.0, height: 4.0 }),
    ];
    for shape in &shapes {
        println!("{}={:.2}", shape.label(), shape.area());
    }
    println!("total={:.2}", total_area(&shapes));
}

