        Sale { id: 2, region: "south", amount: 13 },
        Sale { id: 3, region: "east", amount: 6 },
        Sale { id: 4, region: "west", amount: 13 },
        Sale { id: 5, region: "north", amount: 6 },
        Sale { id: 6, region: "south", amount: 14 },
    ];
    for (region, total) in group_by_region_safe(&sales) {
        println!("{region}={total}");
    }
}

