fn max_value_v2<T: PartialOrd + Copy>(values: &[T]) -> Option<T> {
    let mut best = *values.first()?;
    for value in values.iter().skip(1) {
        if *value > best {
            best = *value;
        }
    }
    Some(best)
}

fn main() {
    let numbers: Vec<i64> = vec![1000, 1003, 1006, 1009, 1012, 1015, 1018, 1021, 1024, 1027, 1030, 1033];
