)

var ErrInsufficientFunds = errors.New("insufficient funds")

type Account struct {
	Owner   string
	Balance int64
}

func NewAccount(owner string, initial int64) *Account {
	return &Account{Owner: owner, Balance: initial}
}

func (account *Account) Deposit(amount int64) error {
	if amount <= 0 {
		return errors.New("amount must be positive")
	}
	account.Balance += amount
	return nil
}

func (account *Account) Withdraw(amount int64) error {
	if amount <= 0 {
		return errors.New("amount must be positive")
	}
	if amount > account.Balance {
		return ErrInsufficientFunds
	}
	account.Balance -= amount
	return nil
}

func main() {
	account := NewAccount("alpha", 1100)
	_ = account.Deposit(160)
	fmt.Println(account.Withdraw(20))
	fmt.Println(account)
	fmt.Println(errors.Is(account.Withdraw(1_000_000), ErrInsufficientFunds))
}

